#[cfg(not(windows))]fn main(){std::process::exit(2)}
#[cfg(windows)]fn main(){let args:Vec<_>=std::env::args().skip(1).collect();let result=(||->std::io::Result<usize>{if args.len()!=3{return Err(std::io::Error::other("expected OWNER_PID PIPE_NAME status|read"))}let pid=args[0].parse().map_err(|_|std::io::Error::other("owner PID required"))?;let op=match args[2].as_str(){"status"=>0,"read"=>2,_=>return Err(std::io::Error::other("scope refused"))};let bytes=computer_link_local_transport::paired_client(&args[1],pid,op)?;Ok(bytes.len())})();match result{Ok(n)=>println!("authenticated response: {n} bytes"),Err(_)=>{eprintln!("pairing or request refused");std::process::exit(2)}}}
